/**
 * Generated by quail.
 *
 * Touch-interaction baseline for https://www.spritecloud.com/agentic-testing. Composed from prims.ts
 * primitives (mobileNav / longPressCTA / swipeHorizontal / pinchCenter
 * / flickScroll / assertHeadingVisible). Runs under an iPhone 13
 * profile so touchscreen events exercise the real touch pipeline.
 *
 * Filter: `npx playwright test --grep @kind:touch`
 */
import { test, expect, devices } from '@playwright/test'
import {
  iPhone,
  mobileNav,
  primaryCTA,
  longPressCTA,
  swipeHorizontal,
  pinchCenter,
  flickScroll,
  assertHeadingVisible,
} from '../prims'

test.use({ ...devices['iPhone 13'] })

test.describe.configure({ mode: 'parallel' })
test.describe('Spritecloud — touch gestures @ https://www.spritecloud.com/agentic-testing', () => {
  test('@kind:touch @smoke long-press on the primary CTA does not double-fire', async ({ page }) => {
    await mobileNav(page, 'https://www.spritecloud.com/agentic-testing')
    const clicks = await longPressCTA(page)
    if (clicks < 0) test.skip()
    expect.soft(clicks, 'tap should fire exactly one click').toBeLessThanOrEqual(1)
  })

  test('@kind:touch @swipe horizontal swipe keeps the page interactive', async ({ page }) => {
    await mobileNav(page, 'https://www.spritecloud.com/agentic-testing')
    await swipeHorizontal(page)
    await assertHeadingVisible(page)
  })

  test('@kind:touch @pinch-zoom synthesised pinch keeps the page interactive', async ({ page }) => {
    await mobileNav(page, 'https://www.spritecloud.com/agentic-testing')
    await pinchCenter(page)
    await assertHeadingVisible(page)
  })

  test('@kind:touch @scroll-momentum rapid vertical swipes do not break the layout', async ({ page }) => {
    await mobileNav(page, 'https://www.spritecloud.com/agentic-testing')
    await flickScroll(page, 5)
    await assertHeadingVisible(page)
  })

  test('@kind:touch @tap-then-rotate tap during orientation change does not duplicate-fire', async ({ browser }) => {
    if (!iPhone.viewport) test.skip()
    const ctx = await browser.newContext(iPhone)
    const page = await ctx.newPage()
    await mobileNav(page, 'https://www.spritecloud.com/agentic-testing')
    const cta = primaryCTA(page)
    if (await cta.count() === 0) { await ctx.close(); test.skip(); return }
    let clicks = 0
    await page.exposeFunction('__quailRotClicked', () => { clicks++ })
    await cta.evaluate(el => el.addEventListener('click', () => (window as any).__quailRotClicked()))
    const box = await cta.boundingBox()
    if (!box) { await ctx.close(); test.skip(); return }
    await page.touchscreen.tap(box.x + box.width / 2, box.y + box.height / 2)
    await page.setViewportSize({ width: iPhone.viewport.height, height: iPhone.viewport.width })
    await page.waitForTimeout(80)
    expect.soft(clicks, 'rotation mid-tap should not double-fire click').toBeLessThanOrEqual(1)
    await ctx.close()
  })
})
